for theta in np.linspace(0,2*np.pi,361)[:-1]:
 v=np.array([np.cos(theta),np.sin(theta),0.])
 cm=2.12*v
 ref=np.array([0.,0.,1.]); b=np.cross(v,ref)
 for rot in np.linspace(0,2*np.pi,36,endpoint=False):
  hs=[]
  for phi in [rot,rot+2*np.pi/3,rot+4*np.pi/3]:
   d=v/3+np.sqrt(8/9)*(np.cos(phi)*ref+np.sin(phi)*b)
   hs.append(cm+1.09*d)
  # normalized clearance metric
  score=10
